def restore_route3_text(path, source):
    if str(path) != "src/data/wild_encounters.json":
        return source
    for label, original in ORIGINAL_ROUTE3.items():
        marker = '"base_label": "' + label + '"'
        i = source.index('"mons": [', source.index(marker))
        assert source[i:i+len(BALANCED_ROUTE3)] == BALANCED_ROUTE3, label
        source = source[:i] + original + source[i+len(BALANCED_ROUTE3):]
    return source

def prior_route3_source(path):
    return restore_route3_text(path, prior_victory_road_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_route3_text(path, source):
    return restore_route3_text(path, restore_prior_victory_road_text(path, source))
